from rest_framework import generics, permissions, status
from rest_framework.response import Response
from django_celery_beat.models import IntervalSchedule, PeriodicTask

class IntervalScheduleDestroyView(generics.DestroyAPIView):
    permission_classes = [permissions.IsAuthenticated]
    queryset = IntervalSchedule.objects.all()

    def destroy(self, request, *args, **kwargs):
        instance = self.get_object()
        org_prefix = f"org_{request.user.organization_id}_"
        # Check if any tasks not owned by the requesting organization use this interval
        unowned_tasks = PeriodicTask.objects.filter(interval=instance).exclude(name__startswith=org_prefix)
        if unowned_tasks.exists():
            return Response(
                {'detail': 'Cannot delete interval schedule referenced by other tenant tasks'},
                status=status.HTTP_403_FORBIDDEN
            )
        instance.delete()
        return Response(status=status.HTTP_204_NO_CONTENT)
